"""Applications, part A: service desk and ITSM, issue trackers and wikis, chat and conferencing, file sharing and office suites, mail, telephony.

Application tiers that people and other systems talk to: stateless nodes (`app`) over a database and file storage that are separate kinds on the diagram.
A product that cannot run as several active instances (it keeps its data on its own disk) is a single node with `stateful` + `backup-required` instead
of `workload`, as Jenkins is: a second node of it is a standby, not a second active instance. The descriptions say which state the product keeps and
where, because that decides what a second node needs."""
from forge import *

FUNCTIONS = {"apps": [
    ("itsm", "Service desk и ITSM", "Service desk and ITSM", "ticket"),
    ("tracker", "Трекеры задач и вики", "Issue trackers and wikis", "clipboard-check"),
    ("chat", "Мессенджеры и конференции", "Chat and conferencing", "message-circle"),
    ("office", "Файлы и офис", "File sharing and office suites", "files"),
    ("mail", "Почтовые серверы и клиенты", "Mail servers and webmail", "mail"),
    ("telephony", "Телефония и VoIP", "Telephony and VoIP", "phone-call"),
]}
IAC = {"itsm": "business", "tracker": "business", "chat": "business", "office": "business", "mail": "business", "telephony": "business"}

ITSM = T["app"] + ["itsm"]
TRACKER = T["app"] + ["tracker"]
WIKI = T["app"] + ["tracker", "wiki"]
CHAT = T["app"] + ["chat"]
MEET = T["app"] + ["chat", "conferencing"]
FILES = T["app"] + ["office", "file-share"]
OFFICE = T["app"] + ["office"]
MAIL = T["app"] + ["mail"]
WEBMAIL = T["app"] + ["mail", "webmail"]
TEL = T["app"] + ["telephony"]
# one active instance by design: the data lives on the node, a second node is a standby (no `workload`, like Jenkins)
SINGLE_TRACKER = ["app", "tracker", "stateful", "backup-required"]
SINGLE_MAIL = ["app", "mail", "stateful", "backup-required"]
SINGLE_TEL = ["app", "telephony", "stateful", "backup-required"]

DC_NODES = ("Узлы Data Center", "Data Center nodes")
